import Foundation
var checks = 0, failures = 0
func expect(_ ok: Bool, _ name: String) { checks += 1; if !ok { failures += 1; print("FAIL: \(name)") } }
expect(!CompletionEditing.hasTextOnCurrentLine(after: ""), "В конце поля используется обычная подсказка")
expect(!CompletionEditing.hasTextOnCurrentLine(after: " "), "Невидимый хвостовой пробел не включает плашку")
expect(!CompletionEditing.hasTextOnCurrentLine(after: "\t \u{00A0}"), "Пробельный хвост в конце поля не считается текстом справа")
expect(!CompletionEditing.hasTextOnCurrentLine(after: " \u{00A0}\nследующий абзац"), "Пробелы перед концом абзаца не включают плашку")
expect(!CompletionEditing.hasTextOnCurrentLine(after: "\nследующий абзац"), "Текст следующего абзаца не включает плашку")
expect(!CompletionEditing.hasTextOnCurrentLine(after: " \r\nследующий абзац"), "Конец строки CRLF отделяет следующий абзац")
expect(!CompletionEditing.hasTextOnCurrentLine(after: "\u{FEFF}"), "Невидимая метка курсора редактора не включает плашку")
expect(!CompletionEditing.hasTextOnCurrentLine(after: "\u{200B} \nследующий абзац"), "Пробел нулевой ширины в хвосте не считается текстом справа")
expect(CompletionEditing.hasTextOnCurrentLine(after: "\u{200B} справа есть текст"), "Невидимая метка перед настоящим текстом не скрывает его")
expect(!CompletionEditing.hasTextOnCurrentLine(after: "\u{200D}"), "Одиночная форматирующая метка не включает плашку")
expect(CompletionEditing.hasTextOnCurrentLine(after: "👨‍👩‍👧"), "Emoji с соединителями остаётся видимым содержимым справа")
expect(CompletionEditing.hasTextOnCurrentLine(after: "\u{0600}"), "Видимый арабский знак категории format не считается пустым хвостом")
expect(CompletionEditing.hasTextOnCurrentLine(after: " справа есть текст"), "Пробел перед настоящим текстом справа сохраняет плашку")
expect(CompletionEditing.hasTextOnCurrentLine(after: "."), "Пунктуация справа считается видимым текстом")
expect(CompletionEditing.hasTextOnCurrentLine(after: "\u{FFFC}"), "Встроенный объект справа не принимается за пустой конец строки")
expect(CompletionEditing.usesUnicodeInsertion(bundleID: "com.tinyspeck.slackmacgap", isElectron: true), "Slack не использует неработающую запись AXSelectedText")
expect(CompletionEditing.usesUnicodeInsertion(bundleID: "app.unknown.electron", isElectron: true), "Electron определяется по движку, а не списку известных приложений")
expect(CompletionEditing.usesUnicodeInsertion(bundleID: "com.apple.Safari", isElectron: false), "Safari сохраняет проверяемую печать Unicode")
expect(CompletionEditing.usesUnicodeInsertion(bundleID: "com.apple.SafariTechnologyPreview", isElectron: false), "Safari Technology Preview сохраняет прежний транспорт")
expect(!CompletionEditing.usesUnicodeInsertion(bundleID: "com.apple.TextEdit", isElectron: false), "Нативный редактор сохраняет запись через AX")
expect(CompletionEditing.currentWord("ивет мир", before: "Пр") == "ивет", "дописывается только начатое слово")
expect(CompletionEditing.currentWord(" мир", before: "Привет") == "", "новое слово не предлагается")
expect(CompletionEditing.currentWord("world", before: "Hello ") == "", "после пробела нет начатого слова")
expect(CompletionEditing.currentWord("-то ещё", before: "что") == "-то", "дефис внутри слова")
expect(CompletionEditing.currentWord("afé!", before: "c") == "afé", "диакритика и граница пунктуации")
expect(CompletionEditing.insertion(" пойдём в парк", before: "Завтра мы", after: " в парк.") == " пойдём", "повтор справа удаляется из вставки")
expect(CompletionEditing.insertion(" дела?", before: "Как", after: "?") == " дела", "пунктуация справа не дублируется")
expect(CompletionEditing.insertion("hello", before: "", after: " world") == "hello", "новый текст справа сохраняется")
expect(CompletionEditing.insertion(" зробити", before: "Успеем", after: " завтра").isEmpty, "украинская вставка в середину строки отклоняется")
expect(CompletionEditing.insertion("мир", before: "при", after: "вет") == "", "нельзя вставлять между половинами существующего слова")
expect(CompletionEditing.insertion(" в парк", before: "Мы идём ", after: " в парк") == "", "повтор всего правого текста не вставляется")
expect(CompletionEditing.synonyms(" хороший, отличный, прекрасный, отличный", original: "хороший") == ["отличный", "прекрасный"], "синонимы без исходного слова и дубликатов")
expect(CompletionEditing.synonyms("1. quick | 2. fast | <|im_end|>", original: "rapid") == ["quick", "fast"], "нумерация и служебный токен очищаются")
expect(CompletionEditing.synonyms("чудовий, гарний, прекрасный", original: "красивый") == ["прекрасный"], "из синонимов исключаются украинские слова")
expect(!CompletionEditing.selectionEligible("можемо зробити це завтра"), "украинское выделение не запускает поиск синонимов")
expect(CompletionEditing.synonyms("ответ: это длинное объяснение вместо списка вариантов из модели", original: "тест").isEmpty, "объяснение не считается синонимом")
expect(CompletionEditing.selectionEligible("важная задача"), "короткая фраза допускается")
expect(!CompletionEditing.selectionEligible("первая\nвторая"), "многострочное выделение исключено")
expect(!CompletionEditing.selectionEligible(String(repeating: "a", count: 121)), "ограничение выделения")
expect(!CompletionEditing.selectionEligible(" "), "пустое выделение исключено")
expect(CompletionEditing.alternatives([" дела, потом", " дела!", " работа", "", " работа "]) == [" дела,", " работа"], "альтернативы одного слова без повторов")
expect(CompletionEditing.choiceKey(keyCode: 18, modifiers: 0, count: 3, selected: 0) == .accept(0), "цифра 1 принимает первый вариант")
expect(CompletionEditing.choiceKey(keyCode: 21, modifiers: 0, count: 3, selected: 0) == .pass, "цифра вне списка идёт в приложение")
expect(CompletionEditing.choiceKey(keyCode: 125, modifiers: 0, count: 3, selected: 0) == .select(1), "стрелка вниз выбирает вариант")
expect(CompletionEditing.choiceKey(keyCode: 36, modifiers: 0, count: 3, selected: 2) == .accept(2), "Enter принимает выбранный вариант")
expect(CompletionEditing.choiceKey(keyCode: 53, modifiers: 0, count: 3, selected: 0) == .dismiss, "Esc скрывает список")
expect(CompletionEditing.choiceKey(keyCode: 18, modifiers: 1 << 20, count: 3, selected: 0) == .pass, "команда с цифрой не перехватывается")
expect(CompletionEditing.synonyms("excellent", original: " good ") == [" excellent "], "пробелы выделения сохраняются при замене")
expect(!CompletionEditing.selectionEligible("good,"), "пунктуация не удаляется вместе со словом при выборе синонима")
expect(CompletionEditing.insertion(" тест", before: "слово ", after: "тестирование") == "тест ", "совпавший префикс соседнего слова не обрезается")
expect(CompletionEditing.insertion("пойдём", before: "Завтра мы", after: " в парк.") == " пойдём", "вставка отделяется от слова слева")
expect(CompletionEditing.insertionAlternatives(["good"], before: "This is a ", after: "result.").first == "good ", "вариант сохраняет разделитель справа")
expect(CompletionEditing.insertion("good,", before: "This is a ", after: "result.") == "good, ", "пунктуация вставки не склеивается со словом справа")
print("completion editing: \(checks) checks, \(failures) failures")
exit(failures == 0 ? 0 : 1)
